param([string]$EnvFile='.\.env')
$ErrorActionPreference='Stop';$v=@{};Get-Content $EnvFile|Where-Object{$_ -match '^[^#].*='}|ForEach-Object{$p=$_ -split '=',2;$v[$p[0].Trim()]=$p[1].Trim()};foreach($n in @('GK_SITE_URL','GK_UNIFIED_API_TOKEN')){if([string]::IsNullOrWhiteSpace($v[$n])){throw "$n fehlt."}}
$site=$v.GK_SITE_URL.TrimEnd('/');$h=@{Authorization='Bearer '+$v.GK_UNIFIED_API_TOKEN};$id=19003;$body=[Text.Encoding]::UTF8.GetBytes('{"id":19003}');$post=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/read-post') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $body;$old=[string]$post.content;$featured=Invoke-RestMethod($site+'/wp-json/wp/v2/posts/19003?_fields=id,featured_media')-TimeoutSec 30;if([long]$featured.featured_media-ne 25819){$restorePayload=[Text.Encoding]::UTF8.GetBytes((@{id=$id;content=$old;featured_media=25819}|ConvertTo-Json -Compress));$restore=Invoke-RestMethod($site+'/wp-json/gk-unified-api/v1/update-post') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $restorePayload;$featuredCheck=Invoke-RestMethod($site+'/wp-json/wp/v2/posts/19003?_fields=id,featured_media')-TimeoutSec 30;if([long]$featuredCheck.featured_media-ne 25819){throw "Beitragsbild-Wiederherstellung nicht unterstützt; aktuell: $($featuredCheck.featured_media)"};Write-Host('BEITRAGSBILD_WIEDERHERGESTELLT: 25819')};$pattern='(?is)<figure\b[^>]*>\s*<img\b[^>]*cropped-ChatGPT-Image-11\.-Juni-2026-02_25_44\.png[^>]*>.*?</figure>\s*';$matches=[regex]::Matches($old,$pattern);if($matches.Count-eq 0-and $old-notmatch'cropped-ChatGPT-Image-11'){Write-Host("FERTIG: Seite=$id | Status=ALREADY_CLEAN");exit 0};if($matches.Count-ne 1){throw "Erwartet wurde exakt ein falsches PON-Bild; gefunden: $($matches.Count)"};$new=[regex]::Replace($old,$pattern,'',1);if($new-match'cropped-ChatGPT-Image-11'){throw 'Falsches Bild ist nach Bereinigung noch vorhanden'}
$root=if(Test-Path(Join-Path $PSScriptRoot '..\GkProductionWorker.sln')){Split-Path -Parent $PSScriptRoot}else{$PSScriptRoot};$backup=Join-Path $root('backups\media-'+(Get-Date -Format 'yyyyMMdd-HHmmss'));New-Item $backup -ItemType Directory -Force|Out-Null;[IO.File]::WriteAllText((Join-Path $backup 'post-19003.html'),$old,[Text.UTF8Encoding]::new($false));$payload=[Text.Encoding]::UTF8.GetBytes((@{id=$id;content=$new}|ConvertTo-Json -Compress));$u=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/update-post') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $payload;if($u.updated-ne$true){throw 'Update nicht bestätigt'};$check=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/read-post') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $body;if([string]$check.content-cne$new){throw 'Speicherprüfung fehlgeschlagen'};$cache=Invoke-RestMethod ($site+'/wp-json/gk-unified-api/v1/clear-cache') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes('{}'));if($cache.cache_cleared-ne$true){throw 'Cache nicht geleert'};Write-Host("FERTIG: Seite=$id | Status=UPDATED_AND_VERIFIED | Backup=$backup")
